// Validación y formateo de datos para el Dashboard
var payload = msg.payload;

var msgGauge = { payload: parseFloat(payload.co_pct) || 0 };
var msgRaw = { payload: "ADC Raw: " + (payload.adc_raw || 0) + " | RSSI: " + (payload.wifi_rssi || 0) + " dBm" };
var msgActuador = {
    payload: payload.actuador === "ENCENDIDO",
    color: payload.actuador === "ENCENDIDO" ? "#d9534f" : "#5cb85c",
    text: payload.actuador
};
var msgEstado = {
    payload: payload.alerta_critica ? "⚠️ PELIGRO CRÍTICO CO" : (payload.actuador === "ENCENDIDO" ? "EXTRAYENDO GAS" : "ATMÓSFERA SEGURA")
};

return [msgGauge, msgActuador, msgRaw, msgEstado];

// =========================================================================
// EVALUACIÓN DE ALERTA CRÍTICA CON RETENCIÓN DE ESTADO (ANTI-SPAM)
// =========================================================================
var data = msg.payload;
var coPct = parseFloat(data.co_pct) || 0;
var ahora = Date.now();

// Obtener estado anterior persistido en el contexto del nodo
var ultimaAlertaTimestamp = context.get('ultimaAlertaTimestamp') || 0;
var alertaPreviamenteActiva = context.get('alertaPreviamenteActiva') || false;

// Ventana mínima de repetición antispam: 60 segundos (60,000 ms)
var VENTANA_ANTISPAM_MS = 60000;
var UMBRAL_CRITICO = 60.0;

if (coPct > UMBRAL_CRITICO) {
    // Condición de disparo: o es la primera vez que supera el umbral, o venció la ventana de antispam
    if (!alertaPreviamenteActiva || (ahora - ultimaAlertaTimestamp > VENTANA_ANTISPAM_MS)) {
        context.set('ultimaAlertaTimestamp', ahora);
        context.set('alertaPreviamenteActiva', true);

        var timestampStr = new Date().toLocaleString("es-MX", { timeZone: "America/Hermosillo" });

        // Construcción de Payload enriquecido para Discord Webhook
        var discordPayload = {
            content: "🚨 **ALERTA CRÍTICA DE MONÓXIDO DE CARBONO (CO) DETECTADA** 🚨",
            embeds: [
                {
                    title: "⚠️ CONDICIÓN DE RIESGO INDUSTRIAL EN PLANTA",
                    description: "Se ha rebasado el umbral seguro de CO (> 60.0%). El sistema de control local ha activado automáticamente el extractor de extracción forzada por relevador óptico.",
                    color: 14431525, // Rojo alerta (#dc3545)
                    fields: [
                        {
                            name: "📊 Concentración de CO Medida",
                            value: "**" + coPct.toFixed(2) + " %** (ADC Raw: " + data.adc_raw + ")",
                            inline: true
                        },
                        {
                            name: "⚙️ Estado del Extractor (Relevador)",
                            value: "**" + data.actuador + "** (GPIO 26 Activo)",
                            inline: true
                        },
                        {
                            name: "🕒 Estampa de Tiempo",
                            value: timestampStr,
                            inline: false
                        },
                        {
                            name: "👨‍💻 Equipo Responsable (Proyecto Integrador IoT)",
                            value: "• **Rol 1 (Hardware & Sensores):** [Nombre Integrante 1] - Mat: [Matrícula 1]\n• **Rol 2 (Comms & Infraestructura):** [Nombre Integrante 2] - Mat: [Matrícula 2]\n• **Rol 3 (Software & Orquestación):** [Nombre Integrante 3] - Mat: [Matrícula 3]\n• **Rol 4 (Integración & Calidad / QA):** [Tu Nombre] - Mat: [Tu Matrícula]",
                            inline: false
                        }
                    ],
                    footer: {
                        text: "Docente: Andrés Salomón Enríquez Ochoa | Materia: Internet de las Cosas"
                    }
                }
            ]
        };

        msg.payload = discordPayload;
        msg.headers = { 'Content-Type': 'application/json' };
        return msg;
    }
} else {
    // Si la concentración ya bajó a zona segura, reseteamos la bandera de estado
    if (alertaPreviamenteActiva && coPct <= 25.0) {
        context.set('alertaPreviamenteActiva', false);
        node.log("CO normalizado por debajo de 25%. Sistema antispam rearmado.");
    }
}

return null; // Si no cumple criterios, no emite mensaje a la red
